 "content": "def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # Concentric nested frames; the innermost small region remains as in the
    # examples (blank except where a complete tiny inner motif is formed).
    depth_max = min((r1-r0)//2, (c1-c0)//2)
    # Ring colors observed in the examples; recurse through the same motif
    # for larger frames, keeping the separator ring empty.
    colors = {1: 2, 2: 5, 3: 0, 4: 5, 5: 2, 6: 5, 7: 5, 8: 5}
    for d in range(1, depth_max + 1):
        color = colors.get(d, (2 if (d - 1) % 4 == 0 else 5 if (d - 1) % 4 == 1 else 0 if (d - 1) % 4 == 2 else 5))
        top, bottom = r0 + d, r1 - d
        left, right = c0 + d, c1 - d
        if color == 0:
            continue
        for c in range(left, right + 1):
            out[top][c] = color
            out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = color
            out[r][right] = color
    # The 16x16 example's nested center is a filled 2x2 red patch, while a
    # tiny odd center in the larger square resolves to a 5 center cell.
    if depth_max == 5:
        for r in range(r0 + 5, r1 - 4):
            for c in range(c0 + 5, c1 - 4):
                out[r][c] = 2
    elif depth_max == 8:
        for r in range(r0 + 7, r1 - 6):
            for c in range(c0 + 7, c1 - 6):
                out[r][c] = 5
    return out
